$caseStudies = ['saas-platform'=>['title'=>'Enterprise SaaS Web Platform','image'=>'img/portfolios/concept-1.svg','sections'=>['The challenge'=>'Disconnected spreadsheets and repeated manual entry make it difficult for teams to share an accurate view of operations.','Discovery & strategy'=>'Map the core workflows with stakeholders, define roles and permissions, and consolidate the most important tasks into one accessible dashboard.','The proposed solution'=>'A modular application with role-based access, documented APIs, background jobs, and audit logs. Release the core workflow first, then expand from observed usage.','How success would be measured'=>'Track task completion time, support requests, error rates, and active usage against a baseline before judging the rollout.']],'d2c-storefront'=>['title'=>'Global D2C Storefront','image'=>'img/portfolios/concept-2.svg','sections'=>['The challenge'=>'Mobile customers struggle to compare products and abandon a lengthy checkout.','Discovery & strategy'=>'Review the product discovery journey, simplify navigation, and test a focused product page with transparent shipping information.','The proposed solution'=>'A responsive storefront with clear product variants, guest checkout, useful validation, and payment-provider integration. Keep images responsive and avoid blocking scripts.','How success would be measured'=>'Measure product-to-cart progression, checkout completion, payment failures, and page performance by device.']],'legal-search'=>['title'=>'Legal Services Organic Growth','image'=>'img/portfolios/concept-3.svg','sections'=>['The challenge'=>'A professional services website does not clearly answer location-specific questions or guide visitors toward an enquiry.','Discovery & strategy'=>'Audit crawlability and existing content, map services to search intent, and prioritize useful service and location pages.','The proposed solution'=>'Clear service navigation, contextual internal links, accurate business information, and enquiry forms with accessible labels and confirmation states.','How success would be measured'=>'Monitor qualified enquiries, indexed pages, non-brand search clicks, and conversion paths. Avoid treating rankings alone as a business outcome.']],'healthcare-portal'=>['title'=>'Healthcare & Telehealth Portal','image'=>'img/portfolios/concept-4.svg','sections'=>['The challenge'=>'Patients need an easier way to find services and request appointments without confusing navigation.','Discovery & strategy'=>'Interview staff about recurring questions and map a short booking request journey with clear expectations.','The proposed solution'=>'An accessible service directory and appointment-request interface with minimal data collection, validation, and staff handover. Sensitive integrations require a separate privacy and security review.','How success would be measured'=>'Evaluate request completion, staff handling time, accessibility issues, and unanswered patient questions.']],'b2b-growth'=>['title'=>'B2B Lead Generation','image'=>'img/portfolios/concept-5.svg','sections'=>['The challenge'=>'Campaign traffic arrives on generic pages, making it difficult to connect spend with qualified enquiries.','Discovery & strategy'=>'Align each campaign with one offer and landing page. Agree with sales on what makes a lead qualified before choosing campaign goals.','The proposed solution'=>'Focused landing pages, validated conversion events, spam controls, CRM field mapping, and a feedback loop for lead quality.','How success would be measured'=>'Compare cost per qualified lead, sales acceptance, conversion lag, and pipeline contribution rather than form submissions alone.']],'hospitality'=>['title'=>'Food & Hospitality Platform','image'=>'img/portfolios/concept-6.svg','sections'=>['The challenge'=>'Customers struggle to find menus, opening hours, and the correct location on mobile devices.','Discovery & strategy'=>'Prioritize the tasks guests need most: discover the menu, choose a location, and make a reservation request.','The proposed solution'=>'A mobile-first website with readable menus, location details, reservation-provider handoff, and lightweight imagery.','How success would be measured'=>'Track menu discovery, booking handoffs, location searches, and performance on slower mobile connections.']]];
$articles = ['scalable-web-architecture'=>['title'=>'Building Resilient & Scalable Web Architectures for B2B Growth','image'=>'img/editorial/code.jpg','sections'=>['Start with the business workflow'=>'Identify the actions customers and staff need to complete. Write down expected traffic, response times, data ownership, and recovery requirements. A clear set of constraints is more useful than choosing a fashionable architecture first.','Keep boundaries clear'=>'Separate presentation, application rules, and persistence. Define API contracts and validation at the boundary. Start with a modular application; split services only when independent scaling or ownership justifies the operational cost.','Build for failure'=>'Set timeouts on external requests, make retryable actions idempotent, and send slow work to background jobs. Test restoration from backup, not just backup creation. Provide useful error states so customers can recover.','Measure before scaling'=>'Track response time, error rates, queue depth, and database queries. Load-test the critical journey with realistic data. Add indexes, caching, or capacity in response to a measured bottleneck and verify the effect.']],'technical-seo-checklist'=>['title'=>'Technical SEO Checklist to Maximize Organic Lead Generation','image'=>'img/editorial/analytics.jpg','sections'=>['Check access and indexing'=>'Confirm that important pages return successful responses and can be reached through internal links. Review robots directives, canonical URLs, redirects, and sitemap entries together. A sitemap does not guarantee indexing.','Organize around intent'=>'Give each service page a distinct purpose. Answer the questions a prospective customer actually asks, explain next steps, and link to supporting material. Consolidate overlapping pages rather than publishing near duplicates.','Improve the experience'=>'Use appropriately sized images, reserve space for media, and reduce unnecessary scripts. Test real forms and navigation on a small screen. Add structured data only when it accurately describes visible content.','Connect search to enquiries'=>'Establish a baseline in your search reporting and analytics. Follow organic landing pages through to qualified enquiries. Review trends over time and annotate major changes so you can distinguish changes in demand from technical issues.']],'reduce-ppc-waste'=>['title'=>'Eliminating Ad Spend Waste in Google & Amazon PPC Campaigns','image'=>'img/editorial/workspace.jpg','sections'=>['Verify the conversion signal'=>'Test the whole enquiry or purchase journey. Avoid counting the same conversion twice and distinguish a raw form submission from a lead sales can use. Account for reporting delays before making changes.','Separate intent'=>'Group campaigns by offer and audience intent. Review search terms regularly, add appropriate exclusions, and ensure the landing page matches the ad promise. Keep brand and discovery activity understandable in reporting.','Improve the landing page'=>'State the offer clearly, show relevant evidence, and ask only for information needed at this stage. Make the primary action easy to find on mobile and show a clear confirmation after submission.','Review quality before raising spend'=>'Compare cost with qualified leads or completed orders, not clicks alone. Change one important variable at a time, record the decision, and allow enough data to assess the result. No bid strategy can repair an unclear offer.']],'custom-software-vs-saas'=>['title'=>'Why Custom Software Outperforms Off-The-Shelf SaaS for Scaling Enterprises','image'=>'img/editorial/code.jpg','sections'=>['Map the fit gap'=>'List the workflows that a standard product handles well and the ones that require workarounds. Include reporting, access control, integrations, and data export. Custom software is most useful when these gaps materially affect operations.','Compare total cost'=>'Include discovery, implementation, hosting, support, security updates, and future changes. Compare these with subscription fees, integration costs, and staff time spent on workarounds. Standard software may remain the better choice for common workflows.','Deliver a narrow first release'=>'Build one complete, high-value workflow before replacing every existing tool. Import a representative data sample, validate permissions, and let actual users test the process. Keep an export path and a rollback plan.','Plan ownership'=>'Decide who will operate the system, review incidents, approve changes, and maintain documentation. A custom system needs an ongoing owner and a sustainable support budget after launch.']],'mobile-checkout'=>['title'=>'Optimizing E-Commerce Checkout Funnels for Mobile Shoppers','image'=>'img/editorial/analytics.jpg','sections'=>['Remove surprises'=>'Show delivery costs, taxes where known, and fulfilment expectations before the final payment step. Let customers understand the total and edit their cart without restarting the process.','Design for touch'=>'Use visible labels, appropriate keyboard types, generous touch targets, and helpful inline errors. Preserve valid fields after an error. Offer guest checkout where the business process permits it.','Make payment recovery clear'=>'Explain pending or failed payments without exposing technical details. Prevent accidental duplicate submissions and offer a safe retry path. Test redirects and return URLs on real mobile browsers.','Measure each step'=>'Record progression from cart to checkout to payment confirmation. Segment by device and payment method. Review error rates and customer feedback alongside conversion rates before choosing the next experiment.']],'ai-customer-acquisition'=>['title'=>'Integrating AI Workflows into B2B Customer Acquisition','image'=>'img/editorial/workspace.jpg','sections'=>['Choose a bounded task'=>'Start with repeatable internal work such as drafting a first response or categorizing inbound questions. Define the expected output and the point where a person reviews it before it reaches a customer.','Control the inputs'=>'Use approved source material and minimize personal information. Set retention and access expectations. Keep untrusted customer text separate from instructions so it cannot redefine the workflow.','Evaluate useful outcomes'=>'Build a small set of representative examples and review accuracy, completeness, and tone. Include ambiguous requests and failures. Track the effort needed to correct an output, not just the time required to generate it.','Keep people accountable'=>'Provide a clear handoff for uncertain results. Log changes to the workflow and review failures regularly. Expand automation only when the evidence shows the quality is reliable enough for the task.']]];
